/* Nội dung bài (được các file bài/*.js điền vào khi tải). */
const BAI = {};
function BAI_ADD(pack){
  const mod = BAI_MODS.find(m => m.id === pack.mod), stage = mod && STEP_STAGE[mod.step];
  pack.lessons.forEach(l => {
    BAI[l.id] = l;
    /* Câu hỏi của bài vào chung ngân hàng câu: quiz, ôn lỗi, thi dùng lại được. #1 đoán trước, #2 quyết định. */
    if (typeof EXAM_ITEMS !== 'undefined') (l.q || []).forEach((it, i) => {
      const id = `${l.id}#${i + 1}`;
      if (!EXAM_ITEMS.some(x => x.id === id))
        EXAM_ITEMS.push({ core:false, difficulty:2, minutes:1, ...it, id, source:l.id, stage, mod:pack.mod,
                          teaches: it.teaches || [l.id] });
    });
  });
}

/* Ghép module đã xuất bản vào chương trình. */
(() => {
  if (typeof STAGES === 'undefined') return;
  BAI_MODS.forEach(m => {
    const st = STAGES.find(s => s.id === STEP_STAGE[m.step]); if (!st || st.mods.some(x => x.id === m.id)) return;
    st.mods.push({ id:m.id, t:m.t, tags:m.tags || '', lessons:BAI_INDEX.filter(b => b.mod === m.id).map(b => b.id),
      caseLink:{ t:'Áp dụng vào một case có bấm giờ', href:'case-thu-vien.html' } });
    const j = typeof JOURNEY !== 'undefined' && JOURNEY.find(x => x.k === m.step);
    if (j && !j.mods.includes(m.id)) j.mods.push(m.id);
  });
})();

/* ---------------- lộ trình theo nghề ----------------
   Mỗi lộ trình = bài cũ đã chọn tay + mọi bài của các module dưới đây, xếp theo THỨ TỰ HÀNH TRÌNH 9 BƯỚC
   (Quan sát → … → Rút insight) rồi theo thứ tự module khai báo. Bài thuộc lộ trình luôn mở: người học digital
   không phải qua đề của chặng khác mới tới bài quảng cáo. Lộ trình 'full' giữ nguyên thứ tự chặng + cổng đề. */
const PATH_MODS = {
  perf:    ['ob07','ob05','kh06','gt02','gt03','gt04','tp07','tp10','kn03','kn06','kn07','kn08','kn04','tn01','tn02','tn03','tn04','tn06','dl01','dl02','dl03','dl04','dl06','dl07','dl08','tu01','tu02','tu06','in01'],
  growth:  ['ob05','ob07','kh06','kh03','gt02','gt03','gt04','gt06','tp10','kn08','kn06','kn05','tn01','tn02','tn04','tn06','dl01','dl02','dl03','dl04','dl06','dl07','dl08','tu01','tu03','tu04','tu05','tu06','in01'],
  content: ['ob05','kh04','kh05','kh10','tp04','tp07','tp08','tp09','kn04','kn05','kn01','tn03','dl07','dl08','in01','in02'],
  brand:   ['ob04','ob06','kh01','kh02','kh04','kh08','tp01','tp02','tp03','tp04','tp05','tp06','tp08','tp09','tp11','kn07','kn09','kn10','tn05','dl05','in02','in03'],
  pmm:     ['ob03','ob04','kh01','kh02','kh03','kh04','kh05','gt05','tp01','tp02','tp11','tn04','tn05','dl01','dl02','tu04','in02','in04'],
  owner:   ['ob01','ob02','ob06','ob07','kh01','kh03','kh08','tp03','tp07','tp11','kn01','kn03','kn04','kn08','tn01','tn04','dl02','dl03','tu03','tu05'],
  mt:      ['ob03','ob04','ob07','kh04','gt01','gt02','gt03','gt04','gt05','tp01','tp08','kn10','dl03','dl09','in02','in03','in04','in05'],
  case:    ['ob07','gt01','gt02','gt03','gt04','gt06','tp01','kn07','dl01','dl02','dl03','dl09','in04','in05'],
};
(() => {
  if (typeof PATHS === 'undefined' || typeof JOURNEY === 'undefined' || typeof STAGES === 'undefined') return;
  const mods = STAGES.flatMap(st => st.mods);
  const modOf = (k) => mods.find(m => m.lessons.includes(k));
  const stepOf = (k) => { const m = modOf(k); const i = m ? JOURNEY.findIndex(j => j.mods.includes(m.id)) : -1; return i < 0 ? 99 : i; };
  PATHS.forEach(p => {
    const list = PATH_MODS[p.id]; if (!list || !p.lessons) return;
    const add = list.flatMap(id => (mods.find(m => m.id === id) || { lessons: [] }).lessons);
    const all = [...new Set([...p.lessons, ...add])];
    const pos = (k) => { const m = modOf(k); const i = m ? list.indexOf(m.id) : -1; return i; };   // module cũ chưa liệt kê: -1, đứng trước trong cùng bước
    p.lessons = all.map((k, n) => ({ k, n })).sort((a, b) => stepOf(a.k) - stepOf(b.k) || pos(a.k) - pos(b.k) || a.n - b.n).map(x => x.k);
  });
})();
